SELECT set_config('request.jwt.claim.sub','f49d6153-1835-4455-81f3-2918d5d3484e',false);
BEGIN;
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is the purpose of a ''dyeing machine''s sample/lab-scale version'' (a small-capacity lab dyeing machine) used in a dye house''s technical department?', '["To run small trial dyeings (lab dips) at low material/chemical cost before committing to full bulk production","Lab-scale machines are used only for the final bulk production run itself","To physically weigh finished bulk fabric after dyeing","To replace the need for any bulk dyeing machine entirely"]'::jsonb, 'To run small trial dyeings (lab dips) at low material/chemical cost before committing to full bulk production', 'Lab-scale dyeing machines let technicians run small, low-cost trial dyeings (lab dips) to develop and verify a recipe before committing significant time, water, chemicals, and fabric to a full bulk production batch — reducing the cost/risk of recipe trial-and-error.', 1, '{"lab-dyeing-machine"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is a key practical challenge in ''scaling up'' a dye recipe from a small lab dip to full bulk production, even when using the exact same percentages?', '["Bulk machines may have different heating rates, liquor circulation patterns, and effective liquor ratios than lab equipment, which can cause the bulk result to differ from the lab dip despite identical percentage recipes","Scaling up a recipe always produces an identical result with zero possible variation between lab and bulk","Recipe scale-up is purely a matter of simple arithmetic with no practical process differences to consider","Bulk dyeing machines never differ from lab machines in any meaningful process characteristic"]'::jsonb, 'Bulk machines may have different heating rates, liquor circulation patterns, and effective liquor ratios than lab equipment, which can cause the bulk result to differ from the lab dip despite identical percentage recipes', 'Even with an identical percentage-based recipe, differences between lab and bulk equipment (heating rate, liquor circulation efficiency, exact liquor ratio achievable, batch size effects) can cause the actual bulk dyeing outcome to differ from the lab dip — a well-known practical challenge requiring careful process matching/adjustment during scale-up.', 2, '{"recipe-scale-up"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is the purpose of running a ''bulk trial'' (a small-scale run on the ACTUAL bulk machine, before committing the full order quantity) in some dyeing operations?', '["To verify that the recipe developed in the lab actually reproduces the target shade correctly on the real bulk equipment, before risking the full order quantity","Bulk trials are never used in any dyeing operation, since lab dips alone are always sufficient","A bulk trial always uses less fabric than a lab dip, making it a cheaper alternative to lab dip testing entirely","Bulk trials exist purely to test the machine''s mechanical function, unrelated to any color/shade verification"]'::jsonb, 'To verify that the recipe developed in the lab actually reproduces the target shade correctly on the real bulk equipment, before risking the full order quantity', 'Since scale-up from lab to bulk isn''t always perfectly predictable, some mills run a smaller-scale trial directly on the actual bulk machine (using the lab-developed recipe) to confirm the shade holds up under real bulk conditions before committing the full order''s fabric quantity to that recipe.', 2, '{"bulk-trial"}'::text[]);
COMMIT;
